"""Render measured original-dataset experiment results; no fitting."""
import argparse,json,hashlib
from pathlib import Path
import pandas as pd
from ml.training import train_updated_asc as exp
ROOT=exp.ROOT

def render(out):
    r=json.loads((out/'metrics.json').read_text());a=r['original_validation'];b=r['smaller_validation'];c=r['comparison']
    old=json.loads((ROOT/'models/reproducibility/legacy_comparison/smaller_dataset_metrics.json').read_text())
    lines=['# Full original dataset experimental training results','',
        'Executed 2026-10-09. Training, labels and features use only `data/legacy/official_farmer_cultivation_2020_2026.csv`. The previous CSV is read solely for dataset comparisons and implementation checks; it never enters a classifier fit. Both datasets and all earlier experiments remain unchanged. No FastAPI production code or prediction gates were changed.','',
        '## Measured outcome','',
        '**Pooled historical accuracy: Random Forest 77.67%; XGBoost 83.02%.** XGBoost exceeds 85% in 2023 and 2024, but neither model achieves 85% across pooled 2023-2025 predictions. The separate 2026 diagnostics are Random Forest 72.12% and XGBoost 68.37%; they were not used for model selection or tuning.','',
        '## Actual source validation','',f"Original dataset: **{a['records']:,} records**. SHA-256: `{a['sha256']}`. Filename and user designation identify this as original/official; this analysis does not independently certify administrative provenance or population completeness.",'']
    def table(headers,rows):
        lines.append('| '+' | '.join(headers)+' |');lines.append('| '+' | '.join(['---']*len(headers))+' |');lines.extend('| '+' | '.join(map(str,row))+' |' for row in rows);lines.append('')
    for title,key in [('Year','year_counts'),('District','district_counts'),('Season','season_counts'),('Crop','crop_counts')]:
        lines.extend([f'### Records per {title.lower()}','']);table([title,'Records'],a[key].items())
    table(['Year','Maha','Yala'],[(y,a['year_season_counts']['Maha'][y],a['year_season_counts']['Yala'][y]) for y in a['year_counts']])
    table(['Actual column','CSV-loaded dtype','Missing'],[(name,dtype,a['missing_values'][name]) for name,dtype in a['columns_and_types'].items()])
    lines.extend([f"Both districts are represented. Missing values: 0; duplicate IDs: {a['duplicate_ids']}; duplicate rows: {a['duplicate_records']}. Dates parse using explicit **month/day/year** (`%m/%d/%Y`), not day/month/year. Invalid dates: {a['invalid_dates']}; harvest before planting: {a['harvest_before_planting']}. Planting range: {a['date_ranges']['Planting_Date']}; harvest range: {a['date_ranges']['Expected_Harvest_Date']}; duration: {a['duration_days'][0]}-{a['duration_days'][1]} days.",'',
        f"Year differs from planting calendar year in {a['year_planting_mismatch']:,} rows. Recorded season-year cohorts are retained, including Maha planting in the previous calendar year; chronological split ordering is verified using actual prediction cutoffs. No records are silently deleted or rewritten.",''])
    table(['Numeric field','Minimum','Maximum','Invalid (nonfinite/nonpositive)'],[(name,*value,a['invalid_numeric'][name]) for name,value in a['numeric_ranges'].items()])
    lines.extend([f"Expected production = acreage x expected yield within 0.011 kg rounding tolerance; mismatches: {a['production_formula_mismatches']}. These checks establish internal validity, not independent agronomic verification.",'', '## Comparison with the smaller dataset','',
        f"The smaller dataset has {b['records']:,} rows versus {a['records']:,} original rows. Shared IDs: {c['shared_ids']:,}; exact semantic matches after date normalization, excluding ID: **{c['exact_semantic_matches_excluding_id']}**. Shared-ID field agreement is shown below. IDs are not reliable cross-file linkage keys for identical plans.",''])
    table(['Shared-ID field','Equal values out of 1,509'],c['shared_id_equal_fields'].items())
    for field in ['Year','District','Season','Crop']:
        lines.extend([f'### {field} coverage comparison','']);table(['Value','Original n/share','Smaller n/share','Smaller/original count ratio'],[(v,f"{m['original_count']} ({m['original_share']:.2%})",f"{m['smaller_count']} ({m['smaller_share']:.2%})",f"{m['smaller_count']/m['original_count']:.2%}" if m['original_count'] else 'undefined') for v,m in c[field].items()])
    lines.extend(['Count ratios are descriptive, not proven inclusion probabilities or sampling fractions: matching IDs describe different records, and the smaller file is not assumed to be random or a literal subset. Relative to original composition, Hambantota is underrepresented and Matara overrepresented in the smaller file. Original Matara coverage is itself sparse (1,001 rows; 6.63%); without district population totals this is not proof of population undercoverage. Mung Beans and Corn have smaller proportions in the smaller file; Bandakka, Brinjal, Green Chillies and Pumpkin have larger proportions.',''])
    table(['Dataset','Year','Maha n/share','Yala n/share'],[(name,y,f"{v['year_season_counts']['Maha'][y]} ({v['year_season_counts']['Maha'][y]/v['year_counts'][y]:.2%})",f"{v['year_season_counts']['Yala'][y]} ({v['year_season_counts']['Yala'][y]/v['year_counts'][y]:.2%})") for name,v in [('original',a),('smaller',b)] for y in v['year_counts']])
    table(['District / crop','Original records','Smaller records'],[(key,a['district_crop_counts'].get(key,0),b['district_crop_counts'].get(key,0)) for key in sorted(set(a['district_crop_counts'])|set(b['district_crop_counts']))])
    lines.extend(['### Harvest-overlap comparison',''])
    table(['Year','Original mean/median plan count','Smaller mean/median plan count','Original mean overlap acres','Smaller mean overlap acres'],[(y,f"{v['original']['Overlap_Plan_Count']['mean']:.2f}/{v['original']['Overlap_Plan_Count']['median']:.2f}",f"{v['smaller']['Overlap_Plan_Count']['mean']:.2f}/{v['smaller']['Overlap_Plan_Count']['median']:.2f}",f"{v['original']['Overlap_Acres']['mean']:.2f}",f"{v['smaller']['Overlap_Acres']['mean']:.2f}") for y,v in c['overlap_by_year'].items()])
    lines.extend(['Overlap counts materially change when the observed cohort changes: same methodology, different record density, district/crop composition, dates and acreage. Because the files are not matching subsets, the causal portion attributable specifically to sampling cannot be isolated. No deduplication or merging was performed across the files.','', '## Features, targets and availability','',
        'The existing documented research method is preserved. Prediction cutoff is immediately before planting; own proposed plan is available. All reference and peer calculations are separately grouped by district/crop/season. Peer plans must be strictly earlier planted, still awaiting expected harvest, and within inclusive +/-14 days of the proposed harvest; same-date peers are excluded. Historical references require earlier recorded years and expected harvest strictly before the cutoff. Each unique observed historical harvest date anchors a +/-14-day acreage and expected-production window within its recorded year. Linear historical acreage percentiles P33/P67 define Low below P33, High above P67 and Medium at/between boundaries (same numerical boundary tolerance as the existing pipeline). Missing history or coincident thresholds remains insufficient_evidence.','',
        'Classifier features: District, Crop, Season, Land_Size_Acres, planting month, harvest month, overlap plan count, own expected production, historical window count, mean historical acreage and expected production. Exact overlap acreage and thresholds determine the target and are excluded from classifier inputs, alongside ID, year and target. No percentile thresholds were tuned.','',
        'Efficient sorted-date/prefix-sum computation avoids repeatedly rebuilding historical windows. It was checked against the untouched generator on a complete original district/crop/season group and against every saved smaller-dataset numerical feature and label. Removing 2025/2026 from input leaves all <=2024 features/labels unchanged. Each fold asserts ordered planting cutoffs and disjoint IDs.','',
        'Availability at planting and expected harvest is assumed because registration/publication timestamps are absent. Expected harvest is not verified completion. Historical windows overlap and depend on observed harvest-date anchors; they are not independent annual samples. Comparing progressive registrations against completed historical windows can bias Low labels. These are research concentration categories, not verified market oversupply or price-loss risk.',''])
    table(['Year','Insufficient-evidence records'],r['insufficient_by_year'].items())
    lines.extend(['All records remain in features_and_labels.csv. Insufficient-evidence rows are explicitly excluded from supervised fitting/scoring.','', '## Historical expanding-window evaluation','',
        'Fixed configurations, seed 42: Random Forest 300 trees; XGBoost 200 trees, depth 3, learning rate 0.05, multiclass objective. All preprocessing is freshly fitted on training rows only. No hyperparameter search, feature selection or model selection was performed. Both models are reported; 2026 is separately diagnostic and excluded from every fit.',''])
    table(['Training cohorts','Test year','Eligible train','Eligible test','Insufficient test','Baseline class','Baseline accuracy'],[(f'2020-{int(y)-1}',y,v['eligible_train'],v['eligible_test'],v['insufficient_test'],v['baseline_class'],f"{v['baseline']['accuracy']:.2%}") for y,v in r['folds'].items()])
    table(['Year','Model','Accuracy','Macro F1','Low precision/recall','Medium precision/recall','High precision/recall'],[(y,name,f"{m['accuracy']:.2%}",f"{m['macro_f1']:.4f}",*[f"{m['per_class'][k]['precision']:.4f}/{m['per_class'][k]['recall']:.4f}" for k in ['Low','Medium','High']]) for y,v in r['folds'].items() for name,m in v['models'].items()])
    def season_tables(items):
        table(['Cohort','Model','Season','n','Accuracy','Macro F1','Medium recall','High recall','Low-only baseline'],[(cohort,name,s,m['records'],f"{m['accuracy']:.2%}",f"{m['macro_f1']:.4f}",f"{m['per_class']['Medium']['recall']:.4f}",f"{m['per_class']['High']['recall']:.4f}",f"{m['classes'].get('Low',0)/m['records']:.2%}") for cohort,models in items for name,v in models.items() for s,m in v['seasons'].items()])
    season_tables([(y,v['models']) for y,v in r['folds'].items()])
    lines.extend(['### Pooled historical results','', 'Pooled accuracy = summed correct predictions / summed eligible records across 2023-2025. Pooled macro F1 is recalculated from row-level predictions, not averaged over folds. Baseline predictions use each fold\'s training majority class, Low.',''])
    table(['Model','Correct/eligible','Accuracy','Macro F1','Medium recall','High recall'],[(name,f"{m['correct']}/{m['records']}",f"{m['accuracy']:.2%}",f"{m['macro_f1']:.4f}",f"{m['per_class']['Medium']['recall']:.4f}",f"{m['per_class']['High']['recall']:.4f}") for name,m in r['pooled'].items()])
    table(['Model','Previous pooled accuracy','Original pooled accuracy','Difference (pp)'],[(name,f"{old['pooled'][name]['accuracy']:.2%}",f"{r['pooled'][name]['accuracy']:.2%}",f"{100*(r['pooled'][name]['accuracy']-old['pooled'][name]['accuracy']):+.2f}") for name in ['Random Forest','XGBoost']])
    table(['Dataset','Test year','Eligible','Low','Medium','High'],[(name,y,m['records'],*[m.get('classes',m.get('class_distribution',{})).get(k,0) for k in ['Low','Medium','High']]) for name,data in [('original',r['folds']),('smaller',old['folds'])] for y,v in data.items() for m in [v['models']['XGBoost']]])
    lines.extend(['The new historical pool contains 6,336 records versus 618 previously. Pooled original labels are Low 4,241 (66.93%), Medium 1,237 (19.52%), High 858 (13.54%); prior labels were Low 409 (66.18%), Medium 162 (26.21%), High 47 (7.61%). Record membership, district/crop composition, historical concentration totals, and labels all change. The accuracy increases of 3.56 points (Random Forest) and 5.67 points (XGBoost) are descriptive across different experiments, not a matched-cohort proof of improved generalization.','',
        'XGBoost meets 85% in 2023 (90.40%) and 2024 (86.99%), but scores 74.62% in 2025 and 83.02% pooled. Random Forest scores 77.67% pooled. Thus >=85% is not demonstrated for the full historical evaluation. Weak Medium recall (XGBoost pooled 31.45%) limits balanced performance; XGBoost often predicts Medium cases as High (615 pooled cases). Legitimate improvements require verified availability/provenance, more independent reference history, investigation of evolving category/feature relationships, and tuning only on earlier rolling validation with a new future holdout. No target or test manipulation is justified.','', '## Separate 2026 diagnostics','', 'Both models are the through-2024 fits used to test 2025. No refitting after historical scoring; no decision was selected from 2026 results.',''])
    table(['Model','Eligible','Accuracy','Macro F1','Low precision/recall','Medium precision/recall','High precision/recall','Baseline accuracy'],[(name,m['records'],f"{m['accuracy']:.2%}",f"{m['macro_f1']:.4f}",*[f"{m['per_class'][k]['precision']:.4f}/{m['per_class'][k]['recall']:.4f}" for k in ['Low','Medium','High']],f"{m['baseline']['accuracy']:.2%}") for name,m in r['diagnostic_2026'].items()])
    season_tables([('2026 diagnostic',r['diagnostic_2026'])])
    lines.extend(['## Confusion matrices','', 'Rows actual; columns predicted: Low, Medium, High.',''])
    matrices=[(f'{y} {n}',m) for y,v in r['folds'].items() for n,m in v['models'].items()]+[(f'Historical pooled {n}',m) for n,m in r['pooled'].items()]+[(f'2026 diagnostic {n}',m) for n,m in r['diagnostic_2026'].items()]
    for title,m in matrices:
        lines.extend([f'### {title}','']);table(['Actual/predicted','Low','Medium','High'],[(k,*row) for k,row in zip(['Low','Medium','High'],m['confusion_matrix'])])
    lines.extend(['## Saved artifacts and reproducibility','',f'Exclusive new directory: `{out.relative_to(ROOT).as_posix()}`. Contains six fitted classifier pipelines and six preprocessing artifacts (through 2022/2023/2024), historical and diagnostic predictions, full features/labels, validation and dataset comparisons in metrics.json, feature schema, exact library versions/parameters, confusion matrices, source hashes, reproduction command and artifact manifest. Earlier models remain unchanged.','',
        'From backend project root, choose a fresh version directory:','', '```powershell',
        '.venv\\Scripts\\python.exe -m ml.training.train_full_original_dataset --output-dir models/experimental/full_original_dataset/v2_reproduction',
        '.venv\\Scripts\\python.exe -m ml.training.report_full_original_dataset --output-dir models/experimental/full_original_dataset/v2_reproduction','```','',
        'Regression tests: pending final recorded result. Source hashes are checked unchanged after execution; preprocessing medians match each fold\'s training-only medians. Frozen artifacts and pooled arithmetic are verified separately. No production files, original CSVs or previous experiments are overwritten.',''])
    if (out/'regression_results.json').exists():
        regression=json.loads((out/'regression_results.json').read_text())
        verification=' All six saved classifiers reproduced fold predictions; through-2024 models also reproduced diagnostic predictions. Both source hashes, preprocessing transformations, and pooled arithmetic verified.' if (out/'artifact_verification.json').exists() else ''
        lines=[line.replace('Regression tests: pending final recorded result.', f"Regression tests: **{regression['passed']} passed, {regression['warnings']} warning in {regression['seconds']}s** (`{regression['command']}`)."+verification) for line in lines]
    (ROOT/'docs/full_original_dataset_training_results.md').write_text('\n'.join(lines),encoding='utf-8')
    for name,m in r['pooled'].items():
        pd.DataFrame(m['confusion_matrix'],index=['Low','Medium','High'],columns=['Low','Medium','High']).to_csv(out/('pooled_'+name.lower().replace(' ','_')+'_confusion_matrix.csv'))
    exp.save(out/'artifact_manifest.json',{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in out.iterdir() if p.is_file() and p.name!='artifact_manifest.json'})
    print('Report written')

if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output-dir',type=Path,required=True);a=p.parse_args();render(a.output_dir.resolve())
